const L=Ledger,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',receipt:'M6 3h12v18l-3-2-3 2-3-2-3 2Zm3 5h6M9 12h6',chart:'M4 20h17M7 16v-5m5 5V5m5 11v-8',wallet:'M3 7V5a2 2 0 0 1 2-2h13v4M3 7h17v14H5a2 2 0 0 1-2-2Zm12 5h5v5h-5Z',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5ZM20 3v4m-2-2h4',settings:'M9 4h6l1 3 3 1 2 5-2 2-1 4-5 2-3-2-4-1-2-5 2-3 1-4Zm3 5a3 3 0 1 0 0 6 3 3 0 0 0 0-6',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-6-6 6 6-6 6',down:'m7 10 5 5 5-5',left:'m14 6-6 6 6 6',right:'m10 6 6 6-6 6',close:'m6 6 12 12M6 18 18 6',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm10-3a3 3 0 1 0 0 6 3 3 0 0 0 0-6',food:'M5 3v7m3-7v7M3 7h7m-4 3v11M17 3c-4 5-4 10 0 10h2V3Zm2 10v8',car:'m5 7 2-4h10l2 4M3 8h18v10H3Zm2 10v3m14-3v3M6 12h2m8 0h2',bag:'M5 7h14l1 14H4ZM8 7V5a4 4 0 0 1 8 0v2',heart:'M12 20 3 11a5 5 0 0 1 9-6 5 5 0 0 1 9 6Z',book:'M3 4h7l2 2 2-2h7v16h-7l-2 1-2-1H3Zm9 2v15',gift:'M3 8h18v5H3Zm2 5v8h14v-8M12 8v13M12 8C3 8 5 0 9 4Zm0 0c9 0 7-8 3-4Z',coin:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm3 5h-5l-1 4h4a3 3 0 0 1 0 6h-4M12 6v13',transfer:'M3 7h17m-4-4 4 4-4 4M21 17H4m4-4-4 4 4 4',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Zm-4 9 3 3 5-6',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14Zm5 12 6 6',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',upload:'M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4',repeat:'M4 7h15l-4-4m4 4-4 4M20 17H5l4 4m-4-4 4-4',target:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 5a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm0 4h.01',moon:'M20 14A9 9 0 0 1 10 3a9 9 0 1 0 10 11',check:'m5 12 4 4L19 6',globe:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 0c5 5 5 13 0 18-5-5-5-13 0-18ZM3 12h18',edit:'m4 15 11-11 5 5L9 20l-6 1Zm9-9 5 5',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',stop:'M6 6h12v12H6Z',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1'};
const icon=n=>`<svg aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.coin}"/></svg>`;
const catIcon=c=>({'餐饮':'food','交通':'car','购物':'bag','健康':'heart','学习':'book','人情':'gift','工资':'coin','居家':'home','娱乐':'spark','旅行':'globe'}[c]||'receipt');
const names={expense:'支出',income:'收入',transfer:'转账',refund:'退款'};
const defaults=[{provider:'deepseek',endpoint:'https://api.deepseek.com/chat/completions',model:'deepseek-flash'},{provider:'kimi',endpoint:'https://api.moonshot.cn/v1/chat/completions',model:'kimi-k3'},{provider:'glm',endpoint:'https://open.bigmodel.cn/api/paas/v4/chat/completions',model:'glm-5.3'},{provider:'custom',endpoint:'https://your-provider.example/v1/chat/completions',model:'your-model'}].map(c=>({...c,configured:false,maxTokens:8192,showReasoning:false}));
const providerName=p=>({deepseek:'DeepSeek',kimi:'Kimi',glm:'GLM',custom:'自定义'}[p]||p);
let S=L.initial(),page='home',month=L.today().slice(0,7),query='',filter='all',drafts=[],configs=defaults,activeJob=null,callbacks=new Map(),seq=Date.now()%10000000000,modalName='',importPending=null,readOnly=false,bootError='',demo=false,sheetScroll=0;
try{const raw=window.Vault?Vault.read():localStorage.getItem('jizhang.ledger.v1');if(raw){const parsed=JSON.parse(raw);S=L.validateBackup(parsed);S.chat=Array.isArray(parsed.chat)?parsed.chat.filter(x=>x&&['user','assistant'].includes(x.role)&&typeof x.text==='string').slice(-20).map(x=>({role:x.role,text:x.text.slice(0,20000)})):[];}}
catch(e){readOnly=true;bootError='本机账本无法读取，已暂停写入以保护原数据。请保留应用数据，先尝试重新打开；也可导出诊断副本或从备份恢复。';}
function persist(){if(readOnly)throw Error('账本处于只读保护，请先恢复有效备份');if(S.transactions.length>30000)throw Error('账单已达 30000 笔，请导出并整理');const raw=JSON.stringify(S);if(raw.length>6000000)throw Error('账本容量已满，请先导出');if(window.Vault){const result=Vault.write(raw);if(result!=='ok')throw Error('本机保存失败，请检查可用空间');}else localStorage.setItem('jizhang.ledger.v1',raw);}
function mutate(fn){const old=JSON.stringify(S);try{fn();persist();return true;}catch(e){S=JSON.parse(old);toast(e.message);return false;}}
function money(n){return S.settings.hide?'••••':L.money(n);}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4300);}
function theme(){const dark=S.settings.theme==='dark'||S.settings.theme==='system'&&matchMedia('(prefers-color-scheme:dark)').matches;document.documentElement.dataset.theme=dark?'dark':'light';window.Device?.theme(dark?'dark':'light');}
const book=()=>S.books.find(b=>b.id===S.settings.book)||S.books[0];
const accName=id=>S.accounts.find(a=>a.id===id)?.name||'未知账户';
const budgetKey=(m=month,c='total')=>`${S.settings.book}:${m}:${c}`;
function budgetValue(c='total',m=month){return S.budgets[budgetKey(m,c)]||0;}
function empty(title,text,ic='receipt'){return `<div class="empty"><div class="empty-icon">${icon(ic)}</div><h3>${title}</h3><p>${text}</p></div>`;}
function txHTML(t){return `<button class="tx-row" data-act="edit-tx" data-id="${esc(t.id)}"><span class="tx-icon">${icon(t.type==='transfer'?'transfer':catIcon(t.category))}</span><span class="tx-main"><b>${esc(t.note||t.category)}</b><small>${esc(t.type==='transfer'?accName(t.account)+' → '+accName(t.to):t.category+' · '+accName(t.account))}${t.tag?' · #'+esc(t.tag):''}</small></span><span class="tx-amount ${t.type==='income'||t.type==='refund'?'income':'expense'}">${t.type==='expense'?'−':t.type==='transfer'?'': '+'}${money(t.amount)}</span></button>`;}
function render(){theme();const nav=[['home','home','概览'],['bills','receipt','账单'],['assistant','spark','助手'],['insights','chart','洞察'],['assets','wallet','资产']];const navHTML=cls=>nav.map(([p,i,n])=>`<button class="${cls} ${page===p?'active':''}" data-act="nav" data-page="${p}" ${page===p?'aria-current="page"':''}>${icon(i)}<span>${n}</span></button>`).join('');const labels={home:'每一笔，都心中有数',bills:'把生活，一笔笔收好',assistant:'记下花费，也读懂生活',insights:'看见钱的去向',assets:'你的生活底气',settings:'简单，也安心'};
 $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">${icon('receipt')}</span>记账</div>${navHTML('nav-button')}<button class="nav-button ${page==='settings'?'active':''}" data-act="nav" data-page="settings">${icon('settings')}设置</button><div class="sidebar-foot">留一点余地给生活。<br>本地账本 · 无需登录</div></aside><main class="content page-enter"><header class="topbar"><div><p class="eyebrow">${L.today().replace(/-/g,'.')} / ${labels[page]}</p><h1>${({home:'记账',bills:'账单',assistant:'记账助手',insights:'收支洞察',assets:'我的资产',settings:'设置'})[page]}</h1></div><div class="top-actions"><button class="book-button" data-act="books" aria-label="切换账本"><span>${esc(book().name)}</span>${icon('down')}</button><button class="icon-button" data-act="nav" data-page="settings" aria-label="设置">${icon('settings')}</button></div></header>${bootError?`<div class="error-banner">${esc(bootError)}<button class="text-button" data-act="raw-export">导出诊断副本</button></div>`:''}${demo?'<div class="demo-label">演示账本 · 示例数据，重新载入恢复你的真实账本</div>':''}${({home:home,bills:bills,assistant:assistant,insights:insights,assets:assets,settings:settings})[page]()}<span class="install-mark">${window.Vault?'':'浏览器预览 · 密钥仅能在 Android 安装版配置'}</span></main><nav class="bottom-nav" aria-label="主导航">${navHTML('')}</nav>${page!=='assistant'&&page!=='settings'?`<button class="fab" data-act="add">${icon('plus')}记一笔</button>`:''}</div>`;}
function monthPicker(){return `<div class="month-picker"><button data-act="month" data-step="-1" aria-label="上个月">${icon('left')}</button><input type="month" id="month" aria-label="统计月份" value="${month}"><button data-act="month" data-step="1" aria-label="下个月">${icon('right')}</button></div>`;}
function home(){const m=L.today().slice(0,7),st=L.stats(S,m),budget=budgetValue('total',m),remain=budget-st.netExpense,pct=budget?Math.min(100,Math.max(0,Math.round(st.netExpense/budget*100))):0;const recent=st.list.slice().sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id)).slice(0,4);const due=S.rules.filter(r=>r.next<=L.today()&&r.template.book===S.settings.book);return `<div class="home-grid"><div><section class="hero"><div class="hero-top"><span>${Number(m.slice(5))} 月总支出 <small style="color:#bed1c0">· 已抵扣退款</small></span><button aria-label="${S.settings.hide?'显示':'隐藏'}金额" data-act="privacy">${icon('eye')}</button></div><div class="hero-value"><span class="currency">¥</span>${money(st.netExpense)}</div><div class="hero-foot"><div><small>本月收入</small><b>¥ ${money(st.income)}</b></div><div><small>本月结余</small><b>¥ ${money(st.balance)}</b></div><span class="pill" style="align-self:end;margin-left:auto">${icon('shield')} 本机私享</span></div></section><section class="entry-panel"><div class="entry-title">${icon('spark')}说一句，帮你记<small>离线也能用</small></div><form id="quick-form" class="entry-line"><input id="quick-input" aria-label="一句话记账" placeholder="比如：早餐18，地铁3" maxlength="2000" autocomplete="off"><button class="send" aria-label="识别账单">${icon('arrow')}</button></form><div class="chips"><button class="chip" data-act="prompt" data-text="今天早餐18元">早餐 18</button><button class="chip" data-act="prompt" data-text="昨天打车32元">打车 32</button><button class="chip" data-act="ask" data-text="帮我分析本月支出，并给出三个节省建议">问问本月花销 ${icon('spark')}</button></div></section><div class="quick-actions"><button data-act="add">${icon('edit')}手动记账</button><button data-act="budgets">${icon('target')}预算计划</button><button data-act="recurring">${icon('repeat')}周期账单</button><button data-act="import">${icon('upload')}导入账单</button></div><section class="section"><div class="section-head"><h2>给消费留一点边界</h2><button class="text-button" data-act="budgets">管理预算</button></div><button class="panel budget-row full" data-act="budgets" style="text-align:left"><span class="ring" style="--pct:${pct}"><b>${budget?pct+'%':'—'}</b></span><span class="budget-text"><h3>${budget?(remain<0?'本月已超出预算':'本月还可以花'):'从一个小预算开始'}</h3><p>${budget?'¥ '+money(Math.abs(remain))+' / 预算 ¥ '+money(budget):'按自己的节奏，安排每一份收入'}</p></span><span class="arrow">›</span></button></section></div><div class="home-right"><section class="section"><div class="section-head"><h2>最近几笔</h2><button class="text-button" data-act="nav" data-page="bills">全部账单 ›</button></div><div class="panel" style="padding-top:5px;padding-bottom:5px">${recent.length?recent.map(txHTML).join(''):empty('从今天的第一笔开始','一杯咖啡、一次出行，都值得被记住。')}</div><div class="insight-note">${icon('spark')}<span>${st.list.length?`这个月已记录 ${st.list.length} 笔。${st.netExpense>0?'打开洞察，看看哪类消费占比最多。':'每一笔记录，都让生活更清楚一点。'}`:'记账不必很复杂。你说花了什么，助手把它整理成账单，确认后才会保存。'}</span></div></section>${due.length?`<section class="section"><div class="section-head"><h2>待处理的周期账单</h2><span class="pill">${due.length} 项</span></div><div class="panel">${due.slice(0,3).map(r=>`<div class="list-item"><div><h3>${esc(r.template.note||r.template.category)}</h3><small>${r.next} · ¥ ${money(r.template.amount)}</small></div><button class="secondary" data-act="post-rule" data-id="${esc(r.id)}">确认入账</button></div>`).join('')}</div></section>`:''}<section class="section"><div class="section-head"><h2>为喜欢的生活存一点</h2><button class="text-button" data-act="goals">储蓄目标 ›</button></div><button class="panel full" style="text-align:left" data-act="goals"><div class="budget-row"><span class="tx-icon">${icon('target')}</span><span class="budget-text"><h3>${esc(S.goals[0]?.name||'下一个小心愿')}</h3><p>${S.goals.length?'已存 ¥ '+money(S.goals[0].saved)+' / ¥ '+money(S.goals[0].target):'给旅行、应急金或一个梦想留出位置'}</p></span><span class="arrow">›</span></div></button></section></div></div>`;}
function bills(){let list=L.stats(S,month).list.filter(t=>(filter==='all'||t.type===filter)&&(!query||[t.note,t.category,t.tag,accName(t.account),(t.amount/100).toFixed(2)].join(' ').toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id));let prev='';const st=L.stats(S,month);return `${monthPicker()}<div class="grid2"><div class="metric"><small>支出 · 抵扣退款后</small><strong>¥ ${money(st.netExpense)}</strong></div><div class="metric"><small>收入</small><strong class="income">¥ ${money(st.income)}</strong></div></div><section class="section"><div class="toolbar"><input id="bill-search" aria-label="搜索账单" placeholder="搜索备注、分类、标签、金额" value="${esc(query)}"><select id="bill-filter" aria-label="收支筛选">${[['all','全部类型'],...Object.entries(names)].map(([k,n])=>`<option value="${k}" ${filter===k?'selected':''}>${n}</option>`).join('')}</select></div><div class="section-head"><small>${list.length} 笔账单 · 点击可编辑</small><button class="text-button" data-act="export-csv">导出 CSV</button></div>${list.length?list.map(t=>{let h='';if(prev!==t.date){prev=t.date;h=`<div class="group-date">${esc(t.date)} · ${['周日','周一','周二','周三','周四','周五','周六'][new Date(t.date+'T12:00:00').getDay()]}</div>`;}return h+txHTML(t);}).join(''):empty(query?'没有匹配的账单':'这个月，还没有记录',query?'试试其他关键词，或切换月份。':'点右下角「记一笔」，或者回到概览说一句。')}</section>`;}
function insights(){const st=L.stats(S,month),cats=Object.entries(st.cats).filter(([,n])=>n>0).sort((a,b)=>b[1]-a[1]),total=cats.reduce((n,[,v])=>n+v,0);let trend=[];for(let i=5;i>=0;i--){const d=new Date(Number(month.slice(0,4)),Number(month.slice(5))-1-i,1),m=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;trend.push({label:d.getMonth()+1+'月',value:Math.max(0,L.stats(S,m).netExpense)});}const max=Math.max(1,...trend.map(x=>x.value)),dayCount=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate(),elapsed=month===L.today().slice(0,7)?new Date().getDate():dayCount;return `${monthPicker()}<div class="grid2"><div class="metric"><small>本月结余</small><strong>¥ ${money(st.balance)}</strong><small>收入 − 支出 + 退款</small></div><div class="metric"><small>日均支出</small><strong>¥ ${money(Math.round(st.netExpense/elapsed))}</strong><small>按${elapsed}个自然日计算</small></div></div><section class="section panel"><div class="section-head"><h2>花在哪里</h2><small>${cats.length} 个分类</small></div>${cats.length?cats.map(([c,n])=>`<div class="category-line"><div class="category-label"><span>${esc(c)}</span><span>¥ ${money(n)} <small>· ${Math.round(n/total*100)}%</small></span></div><div class="track"><div class="fill" style="width:${n/total*100}%"></div></div></div>`).join(''):empty('还没有支出分布','有了支出记录，这里会自动生成分类占比。','chart')}<p class="stat-note">按分类净支出统计；净退款分类不计入正向占比，转账不计入支出。</p></section><section class="section panel"><div class="section-head"><h2>六个月的消费节奏</h2><small>净支出</small></div><div class="bars" role="img" aria-label="${esc(trend.map(x=>x.label+'支出'+money(x.value)+'元').join('，'))}">${trend.map(x=>`<div class="bar-col"><div class="bar" style="height:${Math.max(3,x.value/max*94)}px" title="${money(x.value)}元"></div><small>${x.label}</small></div>`).join('')}</div></section><div class="insight-note">${icon('spark')}<span>${cats.length?'本月正向净支出最多的是「'+esc(cats[0][0])+'」。统计由本机账单计算，你可以请 AI 帮你进一步梳理。':'洞察来自你的真实记录，慢慢记，就会看见变化。'}</span></div><button class="primary full section" data-act="ask" data-text="请根据当前账本的统计摘要分析我的收支，给出三条具体建议。">${icon('spark')}和助手聊聊消费习惯</button>`;}
function assets(){const list=L.balances(S),total=list.reduce((n,a)=>n+a.balance,0),positive=list.reduce((n,a)=>n+Math.max(0,a.balance),0),debt=list.reduce((n,a)=>n+Math.max(0,-a.balance),0);return `<section class="hero"><div class="hero-top"><span>净资产 · 全部账本 / 人民币</span><button data-act="privacy" aria-label="隐藏或显示资产">${icon('eye')}</button></div><div class="hero-value"><span class="currency">¥</span>${money(total)}</div><div class="hero-foot"><div><small>资产余额</small><b>¥ ${money(positive)}</b></div><div><small>负余额 / 负债</small><b>¥ ${money(debt)}</b></div></div></section><section class="section"><div class="section-head"><h2>我的账户</h2><button class="text-button" data-act="account">添加账户 +</button></div>${list.map(a=>`<button class="account-card" data-act="account" data-id="${esc(a.id)}"><div class="account-header"><span>${esc(a.name)}</span><span class="pill">${a.kind==='credit'?'信用账户':'资产账户'}</span></div><strong>¥ ${money(a.balance)}</strong><small>期初余额 ¥ ${money(a.opening)} · 点击管理</small></button>`).join('')}<p class="stat-note">余额 = 期初余额 + 全部账本收入与退款 − 支出 + 转入 − 转出。信用账户期初欠款请输入负数；还款使用账户间转账。</p></section><div class="grid2 section"><button class="panel" data-act="add-transfer">${icon('transfer')}<p style="margin-top:10px">账户间转账</p></button><button class="panel" data-act="goals">${icon('target')}<p style="margin-top:10px">储蓄目标</p></button></div>`;}
function settings(){const configured=configs.filter(x=>x.configured).length;const rows=[['models','spark','模型连接',`${configured} 个已配置 · 当前 ${providerName(S.settings.provider)}`],['search-settings','globe','联网搜索','独立 GLM 搜索 · 每次主动开启'],['books','book','账本管理',`${S.books.length} 个本地账本`],['categories','receipt','分类管理',`${S.categories.length} 个分类`],['budgets','target','预算计划','月度总预算与分类预算'],['recurring','repeat','周期账单','到期后手动确认入账'],['theme','moon','外观','跟随系统 / 浅色 / 深色'],['backup','download','数据备份与导入','JSON 完整备份 · CSV 账单交换'],['about','shield','关于与隐私','免登录 · 账本加密保存在本机']];return `<div class="panel"><div class="budget-row"><span class="assistant-orb">${icon('receipt')}</span><span class="budget-text"><h2>记账</h2><p>把账记清，把日子过轻。</p></span><small>v0.1.0</small></div></div><section class="section panel">${rows.map(([act,ic,title,sub])=>`<button class="settings-row" data-act="${act}">${icon(ic)}<span class="row-text"><b>${title}</b><small>${esc(sub)}</small></span><span class="arrow">›</span></button>`).join('')}</section><div class="insight-note">${icon('shield')}<span>无需注册账号。离线记账、统计和预算免费可用；AI 与搜索使用你自己的服务商密钥与额度。</span></div>`;}
function assistant(){return `<div class="assistant-header"><span class="assistant-orb">${icon('spark')}</span><div><h2>花费随口说，账目慢慢清。</h2><p class="help" style="margin:5px 0 0">${providerName(S.settings.provider)} · ${configs.find(c=>c.provider===S.settings.provider)?.configured?'已配置，联网状态见每次请求':'尚未配置，可先用离线识别'}</p></div></div><div class="chips"><button class="chip" data-act="chat-prompt" data-text="午餐38元，打车26元">整理今天的花费</button><button class="chip" data-act="chat-prompt" data-text="帮我分析本月支出">看看本月花销</button><button class="chip" data-act="chat-prompt" data-text="请搜索官方资料，解释个人记账如何管理应急金">搜一搜记账知识</button><button class="chip" data-act="new-chat">新对话</button></div><div id="draft-area">${draftHTML()}</div><div id="chat-log">${S.chat.length?S.chat.map(x=>`<div class="chat-meta">${x.role==='user'?'你':'记账助手'}</div><div class="chat-bubble ${x.role==='user'?'user':''}">${esc(x.text)}</div>`).join(''):drafts.length?'':`<div class="chat-bubble">你好，我是你的个人记账助手。<br>你可以告诉我“昨天午餐38元，地铁6元”，也可以问问钱花到哪里了。识别出的账单会先给你确认。<br><br><small>离线识别支持简单数字金额；AI 对话需在设置中配置模型。</small></div>`}</div><div id="source-area"></div><div id="job-status" role="status" class="help">${activeJob?'正在生成…':''}</div><form id="chat-form" class="chat-composer ${drafts.length?'has-drafts':''}"><textarea id="chat-input" aria-label="告诉记账助手" placeholder="记一笔，问一问，或者整理今天的花费…" maxlength="4000"></textarea><label class="check"><input id="share-ledger" type="checkbox" ${S.settings.share?'checked':''}>附带当前账本摘要（统计、分类、账户名，无逐笔备注）</label><div class="composer-foot"><label class="check"><input id="online" type="checkbox">${icon('globe')}联网搜索</label><button class="secondary" type="button" data-act="offline-chat">离线识别</button><button class="send" id="chat-send" aria-label="${activeJob?'停止生成':'发送给助手'}" ${activeJob?'type="button" data-act="stop"':''}>${icon(activeJob?'stop':'arrow')}</button></div></form><p class="help">联网只发送本次搜索词（最多128字），请勿输入账号或隐私。搜索摘要会随问题发送给模型；金融信息仅供理解和核查。</p>`;}
function draftHTML(){return drafts.length?`<section class="section"><div class="section-head"><h2>待确认 · ${drafts.length} 笔</h2><button class="text-button" data-act="discard-drafts">全部取消</button></div>${drafts.map((t,i)=>`<div class="draft-card"><div class="budget-row"><span class="tx-icon">${icon(catIcon(t.category))}</span><span class="budget-text"><h3>${esc(t.note||t.category)}</h3><p>${esc(names[t.type])} · ${esc(t.category)} · ${esc(accName(t.account))}</p><small>${t.date}</small></span><b>${money(t.amount)}</b></div><div class="action-row"><button class="secondary" data-act="edit-draft" data-index="${i}">检查 / 修改</button><button class="primary" data-act="save-draft" data-index="${i}">${icon('check')}确认入账</button></div></div>`).join('')}</section>`:'';}
function showSheet(title,html,name='sheet'){if(!$('#overlay').children.length)sheetScroll=window.scrollY;modalName=name||'sheet';document.body.style.overflow='hidden';$('#app').inert=true;$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}" tabindex="-1"><span class="sheet-grab"></span><header class="sheet-head"><h2>${title}</h2><button class="icon-button" data-act="close" aria-label="关闭">${icon('close')}</button></header>${html}</section></div>`;$('.sheet').focus({preventScroll:true});}
function closeSheet(){modalName='';$('#overlay').innerHTML='';$('#app').inert=false;document.body.style.overflow='';window.scrollTo(0,sheetScroll);}
function transactionSheet(id='',draftIndex=-1,type='expense'){const t=draftIndex>=0?drafts[draftIndex]:S.transactions.find(t=>t.id===id)||{type,amount:0,category:'餐饮',account:S.accounts[0].id,to:S.accounts[1]?.id||'',date:L.today(),note:'',tag:'',book:S.settings.book};const options=(arr,v,key='id',label='name')=>arr.map(a=>`<option value="${esc(a[key])}" ${a[key]===v?'selected':''}>${esc(a[label])}</option>`).join('');showSheet(id?'编辑账单':draftIndex>=0?'确认前检查':'记一笔',`<form id="tx-form" data-id="${esc(id)}" data-draft="${draftIndex}"><div class="type-tabs">${Object.entries(names).map(([k,n])=>`<button type="button" data-act="tx-type" data-type="${k}" class="${t.type===k?'active':''}">${n}</button>`).join('')}</div><input id="tx-type" type="hidden" value="${t.type}"><label class="form-field"><span>金额 · 人民币</span><input class="amount-field" id="tx-amount" aria-label="金额" inputmode="decimal" placeholder="0.00" value="${t.amount?(t.amount/100).toFixed(2):''}" required></label><div class="form-row"><label class="form-field"><span>账户 / 转出</span><select id="tx-account">${options(S.accounts,t.account)}</select></label><label class="form-field" id="to-field" ${t.type!=='transfer'?'hidden':''}><span>转入账户</span><select id="tx-to">${options(S.accounts,t.to)}</select></label><label class="form-field" id="cat-field" ${t.type==='transfer'?'hidden':''}><span>分类</span><select id="tx-category">${S.categories.map(c=>`<option ${c===t.category?'selected':''}>${esc(c)}</option>`).join('')}</select></label></div><div class="form-row"><label class="form-field"><span>日期</span><input id="tx-date" type="date" value="${t.date}" required></label><label class="form-field"><span>账本</span><select id="tx-book">${options(S.books,t.book)}</select></label></div><label class="form-field"><span>备注</span><input id="tx-note" maxlength="500" value="${esc(t.note)}" placeholder="花了什么，记一点就好"></label><label class="form-field"><span>标签（可选）</span><input id="tx-tag" maxlength="40" value="${esc(t.tag)}" placeholder="比如：可报销、旅行"></label><button class="primary full" type="submit">${icon('check')}${id?'保存修改':'确认入账'}</button>${id?'<button class="text-button full danger" type="button" data-act="delete-tx" data-id="'+esc(id)+'">删除这笔账单</button>':''}</form>`,'tx');}
function saveTx(form){const index=Number(form.dataset.draft),id=form.dataset.id;const t=L.transaction({id:id||(index>=0?drafts[index].id:undefined),type:$('#tx-type').value,amount:L.cents($('#tx-amount').value),account:$('#tx-account').value,to:$('#tx-to').value,category:$('#tx-category').value,date:$('#tx-date').value,book:$('#tx-book').value,note:$('#tx-note').value,tag:$('#tx-tag').value,recurringKey:id?S.transactions.find(t=>t.id===id)?.recurringKey||'':''},S);if(saveTransaction(t,id)){if(index>=0)drafts.splice(index,1);closeSheet();render();toast('账单已保存到本机');}}
function duplicate(t){return S.transactions.some(x=>x.id!==t.id&&['date','amount','type','account','to','note','book'].every(k=>x[k]===t[k]));}
function saveTransaction(t,id='',allowDuplicate=false){if(duplicate(t)&&!id&&!allowDuplicate){showSheet('这笔账可能已经记过',`<p class="help">同一天存在相同金额、账户和备注。请检查，避免重复。</p><div class="action-row"><button class="secondary" data-act="close">返回检查</button><button class="primary" data-act="force-save" data-tx="${esc(JSON.stringify(t))}">仍然保存</button></div>`,'duplicate');return false;}return mutate(()=>{if(id){const index=S.transactions.findIndex(x=>x.id===id);if(index<0)throw Error('账单不存在');S.transactions[index]=t;}else{if(S.transactions.some(x=>x.id===t.id))throw Error('此账单已经保存');S.transactions.push(t);}});}
function draftInput(text){drafts=L.parseLocal(text,S);page='assistant';render();toast('已整理，确认后才会入账');}
function booksSheet(){showSheet('账本管理',`${S.books.map(b=>`<div class="list-item"><button class="text-button" data-act="select-book" data-id="${esc(b.id)}">${b.id===S.settings.book?'✓ ':''}${esc(b.name)}</button><button class="icon-button" data-act="rename-book" data-id="${esc(b.id)}" aria-label="重命名${esc(b.name)}">${icon('edit')}</button></div>`).join('')}<form id="book-form"><label class="form-field"><span>新建账本（最多50个）</span><input id="book-name" maxlength="40" placeholder="旅行、家庭，或者新的开始" required></label><button class="primary full">添加账本</button></form><p class="help">账本分别统计收支与预算，共享账户余额。修改账本名称不影响历史记录。</p>`,'books');}
function accountSheet(id=''){const a=S.accounts.find(x=>x.id===id);showSheet(a?'管理账户':'添加账户',`<form id="account-form" data-id="${esc(id)}"><label class="form-field"><span>账户名称</span><input id="account-name" maxlength="40" required value="${esc(a?.name||'')}" placeholder="例如：招行储蓄卡"></label><label class="form-field"><span>账户类型</span><select id="account-kind"><option value="asset">资产账户</option><option value="credit" ${a?.kind==='credit'?'selected':''}>信用账户</option></select></label><label class="form-field"><span>期初余额（欠款用负数）</span><input id="account-opening" inputmode="decimal" value="${a?(a.opening/100).toFixed(2):'0.00'}" required></label><p class="help">只输入开始记账前的余额，系统会在此基础上计算所有账单。信用卡欠款如 1200 元，请填 −1200。</p><button class="primary full">保存账户</button>${a?`<button type="button" class="text-button full danger" data-act="delete-account" data-id="${esc(a.id)}">删除空账户</button>`:''}</form>`,'account');}
function budgetsSheet(){const st=L.stats(S,month);showSheet('预算计划',`<p class="help">${month} · ${esc(book().name)}。本月独立设置，退款会抵扣对应分类支出。</p><form id="budget-form"><label class="form-field"><span>本月总预算（留空或0表示不设）</span><input id="budget-total" inputmode="decimal" value="${budgetValue()?(budgetValue()/100).toFixed(2):''}" placeholder="比如 5000"></label>${S.categories.map((c,i)=>`<label class="form-field"><span>${esc(c)} · 已用 ¥ ${money(st.cats[c]||0)}</span><input data-budget-category="${esc(c)}" inputmode="decimal" value="${budgetValue(c)?(budgetValue(c)/100).toFixed(2):''}" placeholder="不设分类预算"></label>`).join('')}<button class="primary full">保存 ${month} 预算</button></form>`,'budgets');}
function categorySheet(){showSheet('分类管理',`${S.categories.map((c,i)=>`<div class="list-item"><span>${esc(c)}</span><button class="icon-button" data-act="delete-category" data-index="${i}" aria-label="删除${esc(c)}分类">${icon('trash')}</button></div>`).join('')}<form id="category-form"><label class="form-field"><span>新分类（最多100个）</span><input id="category-name" maxlength="30" required></label><button class="primary full">添加分类</button></form><p class="help">已有账单和周期计划使用的分类不能删除。</p>`,'categories');}
function recurringSheet(){showSheet('周期账单',`<div class="notice">到期只显示待办，需你确认才会入账。本版不发送系统通知，不会在后台自动扣款或记账。</div>${S.rules.map(r=>`<div class="list-item"><div><h3>${esc(r.template.note||r.template.category)}</h3><p>¥ ${money(r.template.amount)} · ${r.interval==='monthly'?'每月':'每年'}</p><small>下次 ${r.next} · ${esc(S.books.find(b=>b.id===r.template.book)?.name)}</small></div><div>${r.next<=L.today()?`<button class="text-button" data-act="post-rule" data-id="${esc(r.id)}">确认入账</button>`:''}<button class="icon-button danger" data-act="delete-rule" data-id="${esc(r.id)}" aria-label="删除周期计划">${icon('trash')}</button></div></div>`).join('')||empty('把固定开销交给清单','房租、会员、保险，到期时再确认。','repeat')}<button class="primary full section" data-act="new-rule">添加周期账单</button>`,'recurring');}
function ruleSheet(){showSheet('添加周期账单',`<form id="rule-form"><label class="form-field"><span>名称</span><input id="rule-name" maxlength="100" required placeholder="例如：每月房租"></label><div class="form-row"><label class="form-field"><span>支出金额</span><input id="rule-amount" inputmode="decimal" required></label><label class="form-field"><span>周期</span><select id="rule-interval"><option value="monthly">每月</option><option value="yearly">每年</option></select></label></div><label class="form-field"><span>下次到期日</span><input id="rule-date" type="date" value="${L.today()}" required></label><div class="form-row"><label class="form-field"><span>付款账户</span><select id="rule-account">${S.accounts.map(a=>`<option value="${esc(a.id)}">${esc(a.name)}</option>`).join('')}</select></label><label class="form-field"><span>分类</span><select id="rule-category">${S.categories.map(c=>`<option>${esc(c)}</option>`).join('')}</select></label></div><button class="primary full">保存周期计划</button></form>`,'rule');}
function goalsSheet(){showSheet('储蓄目标',`${S.goals.map(g=>`<div class="panel" style="margin-bottom:14px"><div class="section-head"><h3>${esc(g.name)}</h3><button class="text-button danger" data-act="delete-goal" data-id="${esc(g.id)}">删除</button></div><p>¥ ${money(g.saved)} <small>/ ¥ ${money(g.target)}</small></p><div class="track" style="margin-top:12px"><div class="fill" style="width:${Math.min(100,g.saved/g.target*100)}%"></div></div><button class="text-button" data-act="goal-progress" data-id="${esc(g.id)}">更新已存金额</button></div>`).join('')||empty('想要的生活，值得慢慢存','目标进度单独记录，不会移动账户资金。','target')}<form id="goal-form"><label class="form-field"><span>目标名称</span><input id="goal-name" maxlength="40" required placeholder="应急金、旅行基金…"></label><label class="form-field"><span>目标金额</span><input id="goal-amount" inputmode="decimal" required></label><button class="primary full">新建储蓄目标</button></form><p class="help">储蓄进度是手工记录，不计入净资产，也不生成重复收入。</p>`,'goals');}
function modelSheet(provider=S.settings.provider){const c=configs.find(c=>c.provider===provider)||defaults[0];showSheet('模型连接',`<div class="chips">${defaults.map(x=>`<button class="chip ${x.provider===provider?'active':''}" data-act="model-provider" data-provider="${x.provider}">${providerName(x.provider)}</button>`).join('')}</div><div class="notice">${c.configured?'密钥已加密保存于 Android Keystore。保存状态不代表实网验证通过。':'填写自己的开放平台 API Key。手机直接连接服务商，无中转服务器。'}</div><form id="model-form" data-provider="${provider}"><label class="form-field"><span>完整 HTTPS 对话接口</span><input id="model-endpoint" type="url" value="${esc(c.endpoint)}" required spellcheck="false"></label><label class="form-field"><span>模型 ID（可手动修改）</span><input id="model-id" value="${esc(c.model)}" required spellcheck="false"></label><label class="form-field"><span>API Key ${c.configured?'· 留空保留，修改地址需重填':''}</span><input id="model-key" type="password" autocomplete="new-password" placeholder="${c.configured?'已保存，不回显':'仅保存在安装版手机本机'}" ${window.ModelBridge?'':'disabled'}></label><label class="form-field"><span>最大输出 Token</span><select id="model-tokens">${[2048,4096,8192,16384,32768].map(n=>`<option ${c.maxTokens===n?'selected':''}>${n}</option>`).join('')}</select></label><button class="primary full" ${window.ModelBridge?'':'disabled'}>保存并设为当前模型</button><div class="action-row"><button type="button" class="secondary" data-act="test-model" data-provider="${provider}" ${c.configured?'':'disabled'}>测试连接</button><button type="button" class="secondary danger" data-act="remove-model" data-provider="${provider}" ${c.configured?'':'disabled'}>移除密钥</button></div></form><p class="help">API 调用由服务商计费。自定义服务需兼容 Chat Completions SSE 或 JSON 响应。浏览器预览禁用密钥配置，避免在网页环境保存凭证。</p><div id="model-result" class="help" role="status"></div>`,'model');}
function backupSheet(){showSheet('备份与导入',`<p class="help">JSON 包含账本、账户、预算、目标和周期计划，不含 API Key 或对话。备份文件为明文，请妥善保存。卸载前先备份。</p><button class="settings-row" data-act="export-json">${icon('download')}<span class="row-text"><b>导出完整 JSON 备份</b><small>可在其他安装版恢复</small></span>›</button><button class="settings-row" data-act="export-csv">${icon('receipt')}<span class="row-text"><b>导出全部账单 CSV</b><small>适合用 Excel 查看与整理</small></span>›</button><button class="settings-row" data-act="import">${icon('upload')}<span class="row-text"><b>导入 JSON / CSV</b><small>显示预览后，再确认恢复或追加</small></span>›</button><div class="danger-zone"><button class="text-button danger" data-act="clear-ledger">清空本机账本记录</button></div>`,'backup');}
function importFile(){if(demo)throw Error('演示模式不导入真实数据，请先重新载入');if(window.Device){Device.importFile();toast('选择 JSON 备份或本应用格式 CSV');}else{const input=document.createElement('input');input.type='file';input.accept='.json,.csv';input.onchange=async()=>{try{const f=input.files[0];if(!f)return;if(f.size>32000000)throw Error('文件超过32MB');previewImport(await f.text());}catch(e){toast(e.message);}};input.click();}}
window.onImportFile=function(text){try{previewImport(text);}catch(e){toast(e.message);}};
function previewImport(text){if(!text.trim())throw Error('文件为空');const isJSON=text.trim().startsWith('{');if(isJSON){const incoming=L.validateBackup(JSON.parse(text));importPending={type:'json',data:incoming};showSheet('恢复前检查',`<div class="notice">${incoming.books.length} 个账本 · ${incoming.accounts.length} 个账户 · ${incoming.transactions.length} 笔账单</div><p class="help">确认后将替换本机账本、账户、预算和计划。建议先导出当前备份，模型密钥保留。</p><div class="action-row"><button class="secondary" data-act="export-json">先备份当前数据</button><button class="primary" data-act="confirm-import">确认替换并恢复</button></div>`,'import');}else{const all=L.readCSV(text,S);let duplicates=0;const accepted=[];for(const t of all){const same=x=>['date','type','amount','account','to','book','category','note','tag'].every(k=>x[k]===t[k]);if(S.transactions.some(same)||accepted.some(same))duplicates++;else accepted.push(t);}importPending={type:'csv',data:accepted};showSheet('导入前检查',`<div class="notice">读取 ${all.length} 笔 · 待追加 ${accepted.length} 笔 · 跳过重复 ${duplicates} 笔</div><p class="help">仅支持本应用导出的固定 CSV 列格式。CSV 中的账户、账本和分类必须已建立。相同日期、金额、类型、分类、账户、备注与标签视为重复。</p><button class="primary full" data-act="confirm-import">确认追加 ${accepted.length} 笔账单</button>`,'import');}}
function exportFile(text,name,mime){if(window.Device){Device.exportFile(text,name,mime);toast('请选择保存位置，完成后由系统提示');}else{const url=URL.createObjectURL(new Blob([text],{type:mime})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}}
function exportJSON(){const copy={...S,chat:[]};exportFile(JSON.stringify(copy,null,2),`记账_完整备份_${L.today()}.json`,'application/json');}
function summary(){const st=L.stats(S,month);return {账本:book().name,月份:month,币种:'CNY',支出分:st.expense,收入分:st.income,退款分:st.refund,净支出分:st.netExpense,结余分:st.balance,分类净支出分:st.cats,月预算分:budgetValue(),账户:S.accounts.map(a=>({id:a.id,name:a.name})),记录数:st.list.length};}
function request(method,args,handler){if(!window.ModelBridge)throw Error('请在 Android 安装版配置模型');const id=String(++seq);callbacks.set(id,handler);try{ModelBridge[method](id,...args);}catch(e){callbacks.delete(id);throw e;}return id;}
function loadConfigs(){if(window.ModelBridge)request('configs',[],e=>{if(e.kind==='configs'){configs=e.configs;render();}});}
window.onModelEvent=e=>{const cb=callbacks.get(e.id);if(cb){cb(e);if(['done','cancelled','error','configs','saved','removed'].includes(e.kind))callbacks.delete(e.id);}if(e.id===activeJob?.id)receiveChat(e);};
function sendChat(text,offline=false){if(activeJob)throw Error('请先停止当前生成');text=text.trim();if(!text)throw Error('先说点什么吧');if(text.length>4000)throw Error('一次最多 4000 字');if(drafts.length){toast('请先确认或取消现有待确认账单');return;}if(offline){draftInput(text);return;}const configured=configs.find(c=>c.provider===S.settings.provider)?.configured;if(!configured){toast('尚未配置模型，已尝试离线识别');try{draftInput(text);}catch(e){toast(e.message+'；复杂句子可在模型连接中配置。');modelSheet();}return;}const online=!!$('#online')?.checked,share=!!$('#share-ledger')?.checked;
 const prior=S.chat.slice(-12);if(prior.length&&prior[0].role!=='user')prior.shift();const messages=[];for(let i=0;i<prior.length;i+=2){if(prior[i]?.role==='user'&&prior[i+1]?.role==='assistant'){messages.push({role:'user',content:prior[i].text.slice(0,8000)},{role:'assistant',content:prior[i+1].text.slice(0,10000)});}}messages.push({role:'user',content:text});
 mutate(()=>{S.settings.share=share;S.chat.push({role:'user',text});S.chat=S.chat.slice(-20);});page='assistant';render();const id=String(++seq);activeJob={id,text:'',question:text,sources:[],status:'',provider:S.settings.provider};$('#job-status').textContent=online?'正在联网搜索…':'正在理解你的话…';$('#chat-send').type='button';$('#chat-send').dataset.act='stop';$('#chat-send').innerHTML=icon('stop');$('#chat-send').setAttribute('aria-label','停止生成');
 const task={mode:'ledger',date:L.today(),online,query:Array.from(text).slice(0,128).join(''),searchProvider:'glm',messages,context:{book:S.settings.book,accounts:S.accounts.map(a=>({id:a.id,name:a.name})),categories:S.categories},summary:share?summary():null};try{ModelBridge.chat(id,S.settings.provider,JSON.stringify(task));}catch(e){receiveChat({kind:'error',message:e.message,id});}}
function receiveChat(e){if(!activeJob)return;if(e.kind==='phase'){if($('#job-status'))$('#job-status').textContent=e.message;}if(e.kind==='sources'){activeJob.sources=e.sources;showSources();}if(e.kind==='delta'){activeJob.text+=e.text||'';let el=$('#live-reply');if(!el&&$('#chat-log')){$('#chat-log').insertAdjacentHTML('beforeend','<div class="chat-meta">记账助手 · 生成中</div><div id="live-reply" class="chat-bubble"></div>');el=$('#live-reply');}if(el)el.textContent=activeJob.text;}
 if(['done','cancelled','error'].includes(e.kind)){const job=activeJob;let text=job.text;if(e.kind==='done'&&e.finishReason!=='length'){const match=text.match(/```jizhang\s*([\s\S]*?)```/);if(match){try{const items=JSON.parse(match[1]);if(!Array.isArray(items)||items.length>20)throw Error('结构化账单过多');drafts=items.map(raw=>L.transaction({...raw,id:L.uid(),book:S.settings.book},S));text=text.replace(match[0],'').trim()||'已整理，检查后确认入账。';}catch(err){text+='\n\n账单结构未通过校验，未入账：'+err.message;}}}if(e.kind==='done'&&e.finishReason==='length')text+='\n\n输出达到上限，账单未提取，请缩短输入后重试。';if(e.kind==='error')text+=(text?'\n\n':'')+'请求未完成：'+e.message;if(e.kind==='cancelled')text+=(text?'\n\n':'')+'已停止生成，未提取账单。';mutate(()=>{S.chat.push({role:'assistant',text:text||'模型未返回正文，请修改问题后重试。'});S.chat=S.chat.slice(-20);});activeJob=null;render();showSources(job.sources);if(e.kind==='error')toast(e.message);}}
function showSources(sources=activeJob?.sources||[]){if($('#source-area'))$('#source-area').innerHTML=sources.length?`<section class="section"><small>本次检索来源 · 摘要可能不完整</small>${sources.map((s,i)=>`<button class="source-link full" data-act="source" data-url="${esc(s.url)}">[${i+1}] ${esc(s.title)}<br><small>${esc(s.site)} ${esc(s.date)}</small></button>`).join('')}</section>`:'';}
function confirmSheet(title,text,action,id=''){showSheet(title,`<p class="help">${esc(text)}</p><div class="action-row"><button class="secondary" data-act="close">取消</button><button class="primary" data-act="${action}" data-id="${esc(id)}">确认</button></div>`,'confirm');}
function navigate(p){if(activeJob&&p!=='assistant'){toast('请先停止生成，再切换页面');return;}closeSheet();page=p;render();window.scrollTo(0,0);}
function actions(action,el){const id=el.dataset.id;switch(action){
case 'nav':navigate(el.dataset.page);break;
case 'close':closeSheet();break;
case 'privacy':mutate(()=>S.settings.hide=!S.settings.hide);render();break;
case 'add':transactionSheet();break;
case 'add-transfer':transactionSheet('',-1,'transfer');break;
case 'edit-tx':transactionSheet(id);break;
case 'tx-type':$('#tx-type').value=el.dataset.type;document.querySelectorAll('.type-tabs button').forEach(b=>b.classList.toggle('active',b===el));$('#to-field').hidden=el.dataset.type!=='transfer';$('#cat-field').hidden=el.dataset.type==='transfer';break;
case 'delete-tx':confirmSheet('删除这笔账单？','删除后将重新计算余额与统计，可先导出备份。','confirm-delete-tx',id);break;
case 'confirm-delete-tx':if(mutate(()=>S.transactions=S.transactions.filter(t=>t.id!==id))){closeSheet();render();toast('账单已删除');}break;
case 'prompt':$('#quick-input').value=el.dataset.text;$('#quick-input').focus();break;
case 'chat-prompt':$('#chat-input').value=el.dataset.text;$('#chat-input').focus();if(el.dataset.text.includes('搜索'))$('#online').checked=true;break;
case 'ask':navigate('assistant');$('#chat-input').value=el.dataset.text;$('#share-ledger').checked=true;break;
case 'offline-chat':sendChat($('#chat-input').value,true);break;
case 'discard-drafts':drafts=[];render();break;
case 'edit-draft':transactionSheet('',Number(el.dataset.index));break;
case 'save-draft':{const i=Number(el.dataset.index);if(saveTransaction(drafts[i])){drafts.splice(i,1);render();toast('已确认入账');}break;}
case 'force-save':{const t=L.transaction(JSON.parse(el.dataset.tx),S);if(saveTransaction(t,'',true)){drafts=drafts.filter(x=>x.id!==t.id);closeSheet();render();toast('已保存');}break;}
case 'month':{const d=new Date(Number(month.slice(0,4)),Number(month.slice(5))-1+Number(el.dataset.step),1);month=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;render();break;}
case 'books':booksSheet();break;
case 'select-book':mutate(()=>S.settings.book=id);closeSheet();render();break;
case 'rename-book':{const b=S.books.find(b=>b.id===id);showSheet('重命名账本',`<form id="rename-book-form" data-id="${esc(id)}"><label class="form-field"><span>账本名称</span><input id="rename-value" required maxlength="40" value="${esc(b.name)}"></label><button class="primary full">保存名称</button></form>`);break;}
case 'account':accountSheet(id||'');break;
case 'delete-account':if(S.accounts.length<2)throw Error('至少保留一个账户');if(S.transactions.some(t=>t.account===id||t.to===id)||S.rules.some(r=>r.template.account===id||r.template.to===id))throw Error('账户仍有账单或周期计划，不能删除');confirmSheet('删除空账户？','此账户没有关联账单。','confirm-delete-account',id);break;
case 'confirm-delete-account':mutate(()=>S.accounts=S.accounts.filter(a=>a.id!==id));closeSheet();render();break;
case 'budgets':budgetsSheet();break;
case 'categories':categorySheet();break;
case 'delete-category':{const c=S.categories[Number(el.dataset.index)];if(S.categories.length<2||S.transactions.some(t=>t.category===c)||S.rules.some(r=>r.template.category===c))throw Error('此分类仍在使用，或已是最后一个分类');mutate(()=>S.categories=S.categories.filter(x=>x!==c));categorySheet();break;}
case 'recurring':recurringSheet();break;
case 'new-rule':ruleSheet();break;
case 'delete-rule':confirmSheet('删除周期计划？','已确认的历史账单仍会保留。','confirm-delete-rule',id);break;
case 'confirm-delete-rule':mutate(()=>S.rules=S.rules.filter(r=>r.id!==id));recurringSheet();render();break;
case 'post-rule':{const r=S.rules.find(r=>r.id===id);if(!r||r.next>L.today())throw Error('此计划尚未到期');const key=r.id+':'+r.next;const t=L.transaction({...r.template,id:L.uid(),date:r.next,recurringKey:key},S);showSheet('确认周期账单',`<p class="help">${esc(t.note)} · ${t.date}<br>¥ ${money(t.amount)} · ${esc(accName(t.account))}<br>确认后入账，下一期 ${L.nextDate(r.next,r.interval)}。</p><button class="primary full" data-act="confirm-rule" data-id="${esc(id)}">确认这一期已支付</button>`,'confirm');break;}
case 'confirm-rule':{const r=S.rules.find(r=>r.id===id);if(!r||r.next>L.today())throw Error('计划已更新，请重新查看');if(mutate(()=>{const key=r.id+':'+r.next;if(!S.transactions.some(t=>t.recurringKey===key))S.transactions.push(L.transaction({...r.template,id:L.uid(),date:r.next,recurringKey:key},S));r.next=L.nextDate(r.next,r.interval);})){closeSheet();render();toast('周期账单已入账');}break;}
case 'goals':goalsSheet();break;
case 'goal-progress':{const g=S.goals.find(g=>g.id===id);showSheet('更新目标进度',`<form id="progress-form" data-id="${esc(id)}"><p>${esc(g.name)}</p><label class="form-field"><span>累计已存金额（独立进度，不影响账户余额）</span><input id="progress-value" inputmode="decimal" value="${(g.saved/100).toFixed(2)}" required></label><button class="primary full">保存进度</button></form>`);break;}
case 'delete-goal':confirmSheet('删除储蓄目标？','删除此目标的进度，不影响账户和账单。','confirm-delete-goal',id);break;
case 'confirm-delete-goal':mutate(()=>S.goals=S.goals.filter(g=>g.id!==id));goalsSheet();break;
case 'models':modelSheet();break;
case 'model-provider':modelSheet(el.dataset.provider);break;
case 'remove-model':request('remove',[el.dataset.provider],e=>{if(e.kind==='removed'){configs=configs.map(c=>c.provider===e.provider?e.config:c);modelSheet(e.provider);toast('密钥已移除');}else if(e.kind==='error')toast(e.message);});break;
case 'test-model':{if(activeJob)throw Error('请先停止当前生成');const provider=el.dataset.provider;$('#model-result').textContent='正在测试，预计消耗少量服务商额度…';request('chat',[provider,JSON.stringify({mode:'test',date:L.today(),online:false,messages:[{role:'user',content:'只回复：连接成功'}]})],e=>{if(e.kind==='done'){if($('#model-result'))$('#model-result').textContent='连接成功：模型已完整返回。';toast('模型连接成功');}else if(e.kind==='error'){if($('#model-result'))$('#model-result').textContent=e.message;toast(e.message);}});break;}
case 'search-settings':showSheet('联网搜索',`<div class="notice">搜索服务独立于对话模型，使用 GLM 官方 Web Search。请先在模型连接中保存 GLM 官方接口和 Key。</div><p class="help">已配置：${configs.find(c=>c.provider==='glm')?.configured?'是':'否'}。每次在助手输入框主动勾选「联网搜索」才调用。搜索失败会明确提示，不会假装已经联网。</p><p class="help">搜索词取本次输入的前128字，不自动附带账单；结果提供摘要和可点击来源，不自动读取网页全文。</p><button class="primary full" data-act="model-provider" data-provider="glm">配置 GLM</button>`,'search');break;
case 'theme':showSheet('外观',`<div class="chips">${[['system','跟随系统'],['light','浅色'],['dark','深色']].map(([v,n])=>`<button class="chip ${v===S.settings.theme?'active':''}" data-act="set-theme" data-value="${v}">${n}</button>`).join('')}</div><p class="help">字体随手机系统设置缩放，动效跟随减少动态效果设置。</p>`,'theme');break;
case 'set-theme':mutate(()=>S.settings.theme=el.dataset.value);closeSheet();render();break;
case 'backup':backupSheet();break;
case 'import':importFile();break;
case 'confirm-import':{if(!importPending)throw Error('没有待导入数据');const incoming=importPending;const oldReadOnly=readOnly;readOnly=false;const ok=mutate(()=>{if(incoming.type==='json')S=incoming.data;else S.transactions.push(...incoming.data);});if(ok){bootError='';importPending=null;drafts=[];closeSheet();render();toast('数据已保存，导入完成');}else readOnly=oldReadOnly;break;}
case 'export-json':exportJSON();break;
case 'export-csv':exportFile(L.csv(S),`记账_全部账单_${L.today()}.csv`,'text/csv');break;
case 'raw-export':{const raw=window.Vault?Vault.readRaw():localStorage.getItem('jizhang.ledger.v1')||'';exportFile(raw,`记账_诊断副本_${L.today()}.txt`,'text/plain');break;}
case 'clear-ledger':confirmSheet('清空本机账本？','将清除账单、账户、预算、计划、目标和对话；保留模型密钥。请先导出完整备份。','confirm-clear');break;
case 'confirm-clear':if(mutate(()=>S=L.initial())){drafts=[];closeSheet();render();toast('本机账本已清空，模型密钥保留');}break;
case 'new-chat':if(activeJob)throw Error('请先停止生成');if(drafts.length)throw Error('请先确认或取消待确认账单');mutate(()=>S.chat=[]);render();break;
case 'stop':if(activeJob)ModelBridge.cancel(activeJob.id);break;
case 'source':{const url=new URL(el.dataset.url);if(!['https:','http:'].includes(url.protocol))throw Error('无效链接');if(window.Device)Device.open(url.href);else window.open(url.href,'_blank','noopener,noreferrer');break;}
case 'about':showSheet('关于记账',`<div class="assistant-header"><span class="assistant-orb">${icon('receipt')}</span><div><h2>记账 0.1.0</h2><small>个人预览版 · Android 8.0+</small></div></div><p class="help">本机账本与密钥使用 Android Keystore / AES-GCM 加密，关闭系统自动备份；卸载、清除数据或设备损坏可能丢失记录，请主动导出备份。</p><p class="help">AI 请求发送当前对话、日期、当前账户名与分类；仅勾选附带摘要时发送当前月份统计。API Key 仅发送给你配置的 HTTPS 接口。联网搜索只发送搜索词到 GLM，结果摘要再交给对话模型。没有自建云端账户或遥测。</p><p class="help">上限：30000笔账单、100账户、50账本、100分类、200周期计划、200储蓄目标；对话保留最近20条。需要更多空间时请导出归档。</p><p class="help">本版不提供银行自动同步、支付代扣、截图OCR、自动后台记账或系统通知。可用手机键盘语音输入。导入支持本应用 JSON 与 CSV。</p><button class="secondary full" data-act="demo">查看示例账本</button>`,'about');break;
case 'demo':{if(activeJob)throw Error('请先停止生成');demo=true;readOnly=true;S=L.initial();S.accounts[0].opening=250000;S.accounts[1].opening=132800;S.accounts[2].opening=3200000;S.budgets[`${S.settings.book}:${L.today().slice(0,7)}:total`]=600000;const d=L.today();[['expense',3800,'餐饮','午餐 · 一碗热乎的牛肉面','wechat'],['expense',600,'交通','地铁通勤','wechat'],['expense',3200,'餐饮','咖啡时间','wechat'],['expense',26800,'购物','给自己买一本喜欢的书','bank'],['income',1500000,'工资','本月工资','bank']].forEach(([type,amount,category,note,account])=>S.transactions.push(L.transaction({type,amount,category,note,account,date:d},S)));S.goals.push({id:'demo-goal',name:'去看一次山海',target:1200000,saved:360000});page='home';closeSheet();render();break;}
case 'welcome-done':closeSheet();if(!window.Vault)localStorage.setItem('jizhang.welcomed','1');else Vault.welcome();break;
default:break;
}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el)return;try{actions(el.dataset.act,el);}catch(err){toast(err.message);}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;try{switch(f.id){
case 'quick-form':{if(drafts.length)throw Error('请先确认或取消已有待确认账单');const text=$('#quick-input').value.trim();if(!text)throw Error('先写下花了什么吧');try{draftInput(text);}catch(err){if(configs.find(c=>c.provider===S.settings.provider)?.configured)sendChat(text);else{toast(err.message+'；复杂句子可配置 AI 识别');modelSheet();}}break;}
case 'tx-form':saveTx(f);break;
case 'chat-form':sendChat($('#chat-input').value);break;
case 'book-form':{const name=$('#book-name').value.trim();if(!name)throw Error('请输入名称');if(S.books.length>=50||S.books.some(b=>b.name===name))throw Error('账本名称重复或数量已达上限');if(mutate(()=>S.books.push({id:L.uid(),name})))booksSheet();break;}
case 'rename-book-form':{const name=$('#rename-value').value.trim();if(!name||S.books.some(b=>b.name===name&&b.id!==f.dataset.id))throw Error('名称为空或已存在');if(mutate(()=>S.books.find(b=>b.id===f.dataset.id).name=name)){booksSheet();render();}break;}
case 'account-form':{const name=$('#account-name').value.trim(),id=f.dataset.id;if(!name||S.accounts.some(a=>a.name===name&&a.id!==id))throw Error('账户名称为空或已存在');if(!id&&S.accounts.length>=100)throw Error('最多100个账户');const a={id:id||L.uid(),name,opening:L.cents($('#account-opening').value,true),kind:$('#account-kind').value};if(mutate(()=>{if(id)S.accounts[S.accounts.findIndex(a=>a.id===id)]=a;else S.accounts.push(a);})){closeSheet();render();toast('账户已保存');}break;}
case 'budget-form':{const values=[['total',$('#budget-total').value],...Array.from(document.querySelectorAll('[data-budget-category]')).map(el=>[el.dataset.budgetCategory,el.value])];const validated=values.map(([c,v])=>[budgetKey(month,c),!v.trim()||Number(v)===0?0:L.cents(v)]);if(mutate(()=>validated.forEach(([k,v])=>S.budgets[k]=v))){closeSheet();render();toast('预算已保存');}break;}
case 'category-form':{const name=$('#category-name').value.trim();if(!name||S.categories.includes(name)||S.categories.length>=100)throw Error('名称重复、为空或已达100个');if(mutate(()=>S.categories.push(name)))categorySheet();break;}
case 'rule-form':{if(S.rules.length>=200)throw Error('最多200项计划');const date=$('#rule-date').value;if(!L.validDate(date))throw Error('日期无效');const template=L.transaction({type:'expense',amount:L.cents($('#rule-amount').value),date,category:$('#rule-category').value,account:$('#rule-account').value,note:$('#rule-name').value,book:S.settings.book},S);if(mutate(()=>S.rules.push({id:L.uid(),template,next:date,interval:$('#rule-interval').value}))){recurringSheet();render();}break;}
case 'goal-form':{const name=$('#goal-name').value.trim();if(!name||S.goals.length>=200)throw Error('名称为空或已达200项目标');const target=L.cents($('#goal-amount').value);if(mutate(()=>S.goals.push({id:L.uid(),name,target,saved:0})))goalsSheet();break;}
case 'progress-form':{const amount=L.cents($('#progress-value').value,true);if(amount<0)throw Error('已存金额不能为负');if(mutate(()=>S.goals.find(g=>g.id===f.dataset.id).saved=amount))goalsSheet();break;}
case 'model-form':{const provider=f.dataset.provider,raw={endpoint:$('#model-endpoint').value.trim(),model:$('#model-id').value.trim(),key:$('#model-key').value.trim(),maxTokens:Number($('#model-tokens').value),showReasoning:false};request('save',[provider,JSON.stringify(raw)],e=>{if(e.kind==='saved'){configs=configs.map(c=>c.provider===provider?e.config:c);mutate(()=>{if(S.settings.provider!==provider)S.chat=[];S.settings.provider=provider;});render();modelSheet(provider);toast('已加密保存，建议测试连接');}else if(e.kind==='error')toast(e.message);});$('#model-key').value='';break;}
}}catch(err){toast(err.message);}});
document.addEventListener('change',e=>{if(e.target.id==='month'&&/^\d{4}-\d{2}$/.test(e.target.value)){month=e.target.value;render();}if(e.target.id==='bill-filter'){filter=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='bill-search'){const pos=e.target.selectionStart;query=e.target.value;render();$('#bill-search').focus();$('#bill-search').setSelectionRange(pos,pos);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modalName)closeSheet();if(e.key==='Tab'&&$('.sheet')){const els=Array.from($('.sheet').querySelectorAll('button,input,textarea,select,[tabindex]')).filter(x=>!x.disabled&&!x.hidden&&x.offsetParent!==null),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.handleBack=()=>{if(modalName){closeSheet();return true;}if(activeJob){ModelBridge.cancel(activeJob.id);return true;}if(page!=='home'){page='home';render();return true;}return false;};
matchMedia('(prefers-color-scheme:dark)').addEventListener?.('change',theme);
render();loadConfigs();
if(!readOnly&&!(window.Vault?Vault.welcomed():localStorage.getItem('jizhang.welcomed'))){showSheet('你好，开始轻松记账',`<div class="onboarding"><span class="assistant-orb">${icon('receipt')}</span><h2>把账记清，<br>把日子过轻。</h2><p>从一句话开始，让助手整理琐碎的花费。<br>每一笔都由你确认，每一天都心中有数。</p><div class="list-item">${icon('shield')}无需登录 · 账本保存在本机</div><div class="list-item">${icon('spark')}离线能记账 · 配置模型后更聪明</div><div class="list-item">${icon('download')}定期备份 · 数据始终在你手里</div><button class="primary full section" data-act="welcome-done">开始我的第一笔 ${icon('arrow')}</button></div>`,'welcome');}
